        "deposit.methods.commission": "\u041a\u043e\u043c\u0438\u0441\u0441\u0438\u044f",
        "deposit.methods.text": '\u0421\u0438\u0437 \u04e9\u0437\u04af\u04a3\u04af\u0437\u0434\u04af\u043d \u0441\u043e\u043e\u0434\u0430 \u044d\u0441\u0435\u0431\u0438\u04a3\u0438\u0437\u0434\u0438\u043d \u0431\u0430\u043b\u0430\u043d\u0441\u044b\u043d \u0411\u0438\u0448\u043a\u0435\u043a \u0448\u0430\u0430\u0440\u044b\u043d\u0434\u0430 \u0436\u0430\u0439\u0433\u0430\u0448\u043a\u0430\u043d \u043a\u0430\u0430\u043b\u0430\u0433\u0430\u043d "Buleto" \u0441\u043e\u043e\u0434\u0430 \u0430\u044f\u043d\u0442\u0447\u0430\u0434\u0430 \u043a\u043e\u043c\u0438\u0441\u0441\u0438\u044f\u0441\u044b\u0437 \u0442\u043e\u043b\u0443\u043a\u0442\u0430\u0439 \u0430\u043b\u0430\u0441\u044b\u0437:',
        "deposit.methods.address_list": "<li>\u043f\u0440\u043e\u0441\u043f\u0435\u043a\u0442 \u0427\u0443\u0439 52/3 <span>(\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u0435\u0442 \u0443\u043b. \u041a\u0430\u0440\u043f\u0438\u043d\u0441\u043a\u043e\u0433\u043e)</span></li><li>\u0443\u043b. \u0410\u0431\u0434\u0440\u0430\u0445\u043c\u0430\u043d\u043e\u0432\u0430 182 <span>(\u0421\u043e\u0432\u0435\u0442\u0441\u043a\u0430\u044f x \u041a\u0438\u0435\u0432\u0441\u043a\u0430\u044f)</span></li><li>\u0443\u043b. \u0411\u0430\u0439\u0442\u0438\u043a \u0411\u0430\u0430\u0442\u044b\u0440\u0430 55 <span>(\u0421\u043e\u0432\u0435\u0442\u0441\u043a\u0430\u044f x \u0413\u043e\u0440\u044c\u043a\u043e\u0433\u043e)</span></li><li>\u043f\u0440\u043e\u0441\u043f\u0435\u043a\u0442 \u041c\u0438\u0440\u0430 35 <span>(\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u0435\u0442 \u0443\u043b. \u0410\u0439\u043d\u0438)</span></li><li>\u0443\u043b. \u0410\u0445\u0443\u043d\u0431\u0430\u0435\u0432\u0430 116a <span>(\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u0435\u0442 \u0443\u043b. \u0422\u043e\u043a\u0442\u043e\u043d\u0430\u043b\u0438\u0435\u0432\u0430)</span></li><li>\u043f\u0440\u043e\u0441\u043f\u0435\u043a\u0442 \u0416\u0438\u0431\u0435\u043a \u0416\u043e\u043b\u0443 183 <span>(\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u0435\u0442 \u0443\u043b. \u0411\u0443\u0434\u0451\u043d\u043d\u043e\u0433\u043e)</span></li>",
        "deposit.modal.deposit": "\u041f\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0441\u0447\u0451\u0442\u0430",
        "deposit.modal.trial_account": "\u0423\u0447\u0435\u0431\u043d\u044b\u0439 \u0441\u0447\u0451\u0442",
        "deposit.modal.text_1": "\u041f\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0443\u0447\u0435\u0431\u043d\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430 <br/> \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e, \u0435\u0441\u043b\u0438 \u0432\u0430\u0448 \u0431\u0430\u043b\u0430\u043d\u0441 <br/> \u043c\u0435\u043d\u0435\u0435 10,000.00 \u0441\u043e\u043c\u043e\u0432",
