        "deposit.opex.desc": "\u0421\u0438\u0437 Opex \u043a\u0440\u0438\u043f\u0442\u043e\u0432\u0430\u043b\u044e\u0442\u0430 \u0447\u0435\u043a\u0442\u0435\u0440\u0438\u043d \u043a\u043e\u043c\u0438\u0441\u0441\u0438\u044f\u0441\u044b\u0437 \u043d\u0430\u043a\u0442\u0430\u043b\u0430\u0439 \u0430\u043a\u0447\u0430\u0433\u0430 \u044d\u043a\u0438 \u0436\u043e\u043b \u043c\u0435\u043d\u0435\u043d \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0441\u0430\u04a3\u044b\u0437 \u0431\u043e\u043b\u043e\u0442:",
