        "footer.menu.help": "\u0416\u0430\u0440\u0434\u0430\u043c",
        "footer.text_title": "\u0422\u043e\u0431\u043e\u043a\u0435\u043b\u0434\u0438\u043a\u0442\u0435\u0440 \u0442\u0443\u0443\u0440\u0430\u0441\u044b\u043d\u0434\u0430 \u044d\u0441\u043a\u0435\u0440\u0442\u04af\u04af",
        "footer.text": "<p>\u0411\u0443\u043b \u0441\u0430\u0439\u0442 \u0442\u0430\u0440\u0430\u0431\u044b\u043d\u0430\u043d \u0441\u0443\u043d\u0443\u0448\u0442\u0430\u043b\u0433\u0430\u043d \u043a\u0430\u0440\u0436\u044b\u043b\u044b\u043a \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0438\u044f\u043b\u0430\u0440 \u0436\u043e\u0433\u043e\u0440\u043a\u0443 \u0434\u0435\u04a3\u0433\u044d\u044d\u043b\u0434\u0435\u0433\u0438 \u0442\u043e\u0431\u043e\u043a\u0435\u043b\u0434\u0438\u043a\u0442\u0438 \u0430\u043b\u044b\u043f \u043a\u0435\u043b\u0438\u0448\u0438 \u043c\u04af\u043c\u043a\u04af\u043d. \u0411\u0443\u043b \u0441\u0430\u0439\u0442 \u0442\u0430\u0440\u0430\u0431\u044b\u043d\u0430\u043d \u0441\u0443\u043d\u0443\u0448\u0442\u0430\u043b\u0433\u0430\u043d \u0444\u0438\u043d\u0430\u043d\u0441\u044b\u043b\u044b\u043a \u043a\u044b\u0437\u043c\u0430\u0442\u0442\u0430\u0440\u0434\u044b \u0436\u0430\u043d\u0430 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0442\u0435\u0440\u0434\u0438 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0443 \u043c\u0435\u043d\u0435\u043d, \u0441\u0438\u0437 \u043e\u043b\u0443\u0442\u0442\u0443\u0443 \u0444\u0438\u043d\u0430\u043d\u0441\u044b\u043b\u044b\u043a \u0436\u043e\u0433\u043e\u0442\u0443\u0443\u043b\u0430\u0440\u0433\u0430 \u0443\u0447\u0443\u0440\u0430\u043f \u0436\u0435 \u043a\u0435\u043f\u0438\u043b\u0434\u0438\u043a \u0441\u043e\u043e\u0434\u0430 \u044d\u0441\u0435\u0431\u0438\u04a3\u0438\u0437\u0434\u0435\u0433\u0438 \u0430\u043a\u0447\u0430 \u043a\u0430\u0440\u0430\u0436\u0430\u0442\u0442\u0430\u0440\u044b\u043d \u0442\u043e\u043b\u0443\u0433\u0443 \u043c\u0435\u043d\u0435\u043d \u0436\u043e\u0433\u043e\u0442\u0443\u043f \u0430\u043b\u044b\u0448\u044b\u04a3\u044b\u0437 \u043c\u04af\u043c\u043a\u04af\u043d. \u0421\u0443\u0440\u0430\u043d\u044b\u0447, \u0431\u0430\u0440\u0434\u044b\u043a \u043a\u0430\u0440\u0436\u044b\u043b\u044b\u043a \u0442\u043e\u0431\u043e\u043a\u0435\u043b\u0434\u0438\u043a\u0442\u0435\u0440\u0434\u0438 \u0431\u0430\u0430\u043b\u043e\u043e \u0436\u0430\u043d\u0430 \u0441\u043e\u043e\u0434\u0430 \u0430\u043b\u0434\u044b\u043d\u0434\u0430 \u043a\u04e9\u0437 \u043a\u0430\u0440\u0430\u043d\u0434\u044b\u0441\u044b\u0437 \u043a\u0430\u0440\u0436\u044b\u043b\u044b\u043a \u043a\u0435\u04a3\u0435\u0448\u0447\u0438 \u043c\u0435\u043d\u0435\u043d \u0430\u043a\u044b\u043b\u0434\u0430\u0448\u0430\u0442. \u0411\u0443\u043b\u0435\u0442\u043e (Buleto) \u0431\u0443\u043b \u0441\u0430\u0439\u0442\u0442\u0430 \u043a\u043e\u043b\u0434\u043e\u043d\u0443\u0443\u0447\u0443\u043d\u0443\u043d \u0430\u0440\u0430\u043a\u0435\u0442\u0442\u0435\u0440\u0438\u043d\u0435 \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0448\u0442\u0443\u0443 \u0442\u04af\u0437, \u043a\u044b\u0439\u044b\u0440 \u0436\u0435 \u043a\u043e\u043a\u0443\u0441\u0442\u0430\u043d \u043a\u0435\u043b\u0442\u0438\u0440\u0438\u043b\u0433\u0435\u043d \u0437\u044b\u044f\u043d\u0434\u0430\u0440 \u0436\u0435 \u0431\u0430\u0448\u043a\u0430 \u0437\u044b\u044f\u043d \u04af\u0447\u04af\u043d \u0436\u043e\u043e\u043f\u0442\u0443\u0443 \u044d\u043c\u0435\u0441.</p>",
        "footer.text_2": "<p>\u0421\u0430\u0439\u0442, \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u043d\u044b\u0439 \u043d\u0430 \u0434\u043e\u043c\u0435\u043d\u0435 buleto.com \u2014 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 Binolux Ltd., \u0430\u0434\u0440\u0435\u0441 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438: Suite 305, Griffith Corporate Centre, P.O. Box 1510, Beachmont, Kingstown, St. Vincent and the Grenadines. \u0410\u0433\u0435\u043d\u0442\u043e\u043c \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Tradeford; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 12076073, \u0430\u0434\u0440\u0435\u0441: Suite 23057 8 Shepherd Market, Mayfair, London W1J 7JY, United Kingdom.</p>",
        "footer.copyright": "\xa9 {year} \u0411\u0440\u043e\u043a\u0435\u0440\u0434\u0438\u043a \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0411\u0443\u043b\u0435\u0442\u043e (Buleto). \u0411\u0430\u0440\u0434\u044b\u043a \u0443\u043a\u0443\u043a\u0442\u0430\u0440 \u043a\u043e\u0440\u0433\u043e\u043b\u0433\u043e\u043d.",
